package quebec.culture.donnees;
import android.app.*;import android.content.*;import android.os.*;import android.widget.*;
public class RiskRegisterActivity extends Activity{private final String[] risks={"Qualité ou incohérence des données","Retard de cartographie vers la norme","Disponibilité de l’équipe","Dépendance à un fournisseur","Droits, licences ou consentements","Dépassement de budget","Perte ou corruption de données","Changement de portée du projet"};@Override public void onCreate(Bundle b){super.onCreate(b);Ui.bars(this);SharedPreferences p=getSharedPreferences("risks",0);LinearLayout r=Ui.root(this);r.addView(Ui.text(this,"Registre des risques",27,true));for(int i=0;i<risks.length;i++){final int n=i;LinearLayout box=Ui.panel(this);box.addView(Ui.text(this,risks[i],17,true));Spinner level=new Spinner(this);level.setAdapter(new ArrayAdapter<>(this,android.R.layout.simple_spinner_dropdown_item,new String[]{"Faible","Moyen","Élevé"}));level.setSelection(p.getInt("level"+i,1));box.addView(level);EditText mitigation=Ui.field(this,"Mesure de mitigation",p.getString("mitigation"+i,""));box.addView(mitigation);Button save=Ui.secondary(this,"Enregistrer");save.setOnClickListener(v->p.edit().putInt("level"+n,level.getSelectedItemPosition()).putString("mitigation"+n,mitigation.getText().toString()).apply());box.addView(save);r.addView(box);}setContentView(Ui.wrap(this,r));}}
